package com.theaimartco.taim;

import android.content.Context;
import android.content.SharedPreferences;
import com.google.firebase.messaging.FirebaseMessaging;
import org.json.*;
import java.lang.ref.WeakReference;

/**
 * Firebase Cloud Messaging extension (channel {@code taim.fcm}). Generated by project.py --fcm.
 * Data messages are persisted (latest 32) so none are lost while no activity is attached, and are
 * delivered live when one is. Notification messages received in the background are displayed by
 * the system; tapping one launches the activity with its data in the launch intent.
 */
// commit(): messages arrive in a short-lived service whose process may die right after delivery.
@android.annotation.SuppressLint("ApplySharedPref")
public final class TaimFcm implements TaimExtension, TaimPlugin {
    static final String CHANNEL="taim.fcm", PREFS="taim.fcm";
    private static final int MAX_MESSAGES=32;
    static volatile WeakReference<TaimActivity> live=new WeakReference<>(null);

    @Override public void attach(TaimActivity activity){live=new WeakReference<>(activity);activity.registerTaimPlugin(CHANNEL,this);}

    @Override public void call(String method,JSONObject args,Result result){
        try{
            FirebaseMessaging messaging=FirebaseMessaging.getInstance();
            switch(method){
                case "token":messaging.getToken().addOnCompleteListener(task->{if(task.isSuccessful() && task.getResult()!=null)result.success(task.getResult());else result.error("unavailable");});return;
                case "deleteToken":messaging.deleteToken().addOnCompleteListener(task->{if(task.isSuccessful())result.success(null);else result.error("unavailable");});return;
                case "subscribe":case "unsubscribe":{
                    String topic=args.getString("topic");if(!topic.matches("[a-zA-Z0-9\\-_.~%]{1,900}"))throw new IllegalArgumentException();
                    (method.equals("subscribe")?messaging.subscribeToTopic(topic):messaging.unsubscribeFromTopic(topic))
                        .addOnCompleteListener(task->{if(task.isSuccessful())result.success(null);else result.error("unavailable");});return;
                }
                case "autoInit":messaging.setAutoInitEnabled(args.getBoolean("enabled"));result.success(null);return;
                case "pending":{
                    TaimActivity host=live.get();if(host==null){result.error("unavailable");return;}
                    SharedPreferences prefs=host.getSharedPreferences(PREFS,Context.MODE_PRIVATE);
                    JSONArray messages=new JSONArray(prefs.getString("messages","[]"));
                    prefs.edit().putString("messages","[]").commit();
                    result.success(messages);return;
                }
                default:result.error("invalid");
            }
        }catch(JSONException | IllegalArgumentException bad){result.error("invalid");}
        catch(IllegalStateException notConfigured){result.error("unsupported");} // missing google-services.json
    }

    /** Persist first, then deliver live. Called on the messaging service's worker thread. */
    static void deliver(Context context,JSONObject event){
        try{
            if("message".equals(event.optString("type"))){
                SharedPreferences prefs=context.getSharedPreferences(PREFS,Context.MODE_PRIVATE);
                synchronized(TaimFcm.class){
                    JSONArray messages=new JSONArray(prefs.getString("messages","[]"));messages.put(event.getJSONObject("message"));
                    JSONArray bounded=new JSONArray();for(int i=Math.max(0,messages.length()-MAX_MESSAGES);i<messages.length();i++)bounded.put(messages.get(i));
                    prefs.edit().putString("messages",bounded.toString()).commit();
                }
            }
            TaimActivity host=live.get();
            if(host!=null && !host.isFinishing())host.runOnUiThread(()->host.emitTaimPluginEvent(CHANNEL,event));
        }catch(JSONException ignored){}
    }
}
